arguments.script:
export const meta = {
  name: 'mythosmini-quality-push',
  description: 'Fan-out analysis to design the highest-scoring 1M model training run',
  phases: [
    { title: 'Analyze', detail: 'parallel readers over journal, code, and external research' },
    { title: 'Verify', detail: 'adversarial check of top proposals' },
    { title: 'Synthesize', detail: 'ranked implementation plan' },
  ],
}

const FINDINGS = {
  type: 'object',
  required: ['findings'],
  properties: {
    findings: {
      type: 'array',
      items: {
        type: 'object',
        required: ['title', 'detail', 'expected_gain', 'effort', 'risk'],
        properties: {
          title: { type: 'string' },
          detail: { type: 'string', description: 'concrete, implementable description with file paths and exact changes' },
          expected_gain: { type: 'string', description: 'expected benchmark/throughput impact and why' },
          effort: { type: 'string', enum: ['small', 'medium', 'large'] },
          risk: { type: 'string' },
        },
      },
    },
  },
}

const VERDICT = {
  type: 'object',
  required: ['is_sound', 'reasoning', 'fix_if_flawed'],
  properties: {
    is_sound: { type: 'boolean' },
    reasoning: { type: 'string' },
    fix_if_flawed: { type: 'string' },
  },
}

phase('Analyze')
const CONTEXT = `Repo: /home/lane/MythosMini — a 1,050,241-param byte-level (vocab 257) looped-shared-block transformer trained on fineweb-edu, benchmarked on WikiText-2 byte PPL, BLiMP, ARC-Easy against the Tiny-ML leaderboard (overall = mean of blimp, arc, normalized wiki score). Current pipeline: procedural Dyck warmup -> 2B-token training (NAdamW, WSD schedule) -> 3-round recursive STM -> benchmark all checkpoints -> SLERP tournament -> SFT instruct phase -> instruct SLERP. Architecture: 4 prelude + 1 shared block looped 2-6x with per-loop LoRA + 4 coda, dim 96, RMSNorm/RoPE/SwiGLU, tied embeddings, DSA-style sparse attention (shared model-level lightning indexer, top-128 keys, 64 local window, FlexAttention short path, chunked long path, 1M max context), FP4 E2M1 QAT on all linears. Recent regression: moving the indexer from per-attention to one shared model-level indexer + detaching the indexer bias for prelude/coda blocks raised throughput 0.85->1.19 Mtok/s but the verification run scored 59.47 overall vs 60.40 before, AND its STM round 3 NaN-diverged (prior runs' round 3 gave +0.57; NaN also seen once before with output-embedding centering). All-time best: 60.41 (recursive STM on dense attention, commit accd37b). GPU: one RTX 5090 32GB, torch 2.10.0+cu128. Known: full-model torch.compile broken (inductor dtype bug + flex recompile issues), STM phase runs at only ~76 ktok/s vs training 1.19 Mtok/s.`

const results = await parallel([
  () => agent(`${CONTEXT}\n\nRead /home/lane/MythosMini/journal.md IN FULL and /home/lane/MythosMini/scores.md. Extract every technique that was tried with its measured outcome. Produce findings: which proven-good techniques are NOT currently in the default pipeline (or were weakened), which failed approaches must not be retried, and what the data says about where the 59.47 vs 60.40 regression came from. Be specific about numbers.`, { label: 'history-miner', phase: 'Analyze', schema: FINDINGS }),
  () => agent(`${CONTEXT}\n\nRead /home/lane/MythosMini/src/mythosmini/model/transformer.py, src/mythosmini/training/loop.py, src/mythosmini/training/stm.py, src/mythosmini/training/optimizer.py, src/mythosmini/training/scheduler.py, src/mythosmini/config.py. Hunt for QUALITY bugs and theory problems: (1) is the shared model-level indexer (selection computed from embedding output, reused by all 9 blocks incl. prelude/coda with detached bias) theoretically weaker than per-layer indexers, and how to get quality back cheaply? (2) What plausibly causes STM round-3 NaN at constant lr 3e-4 on FP4+sparse weights (look at the detached-bias gradient path, FP4 STE, the indexer gate growth, missing eps/clamps)? Propose concrete fixes with exact code locations. (3) Any other quality-harming detail (init, lr, schedule, loop sampling, tied embedding scale).`, { label: 'code-auditor', phase: 'Analyze', schema: FINDINGS }),
  () => agent(`${CONTEXT}\n\nResearch via web search: state-of-the-art techniques (2024-2026) for maximizing quality of SUB-10M-parameter language models. Focus on: hyperparameter scaling laws for tiny models (muP, depth/width, lr vs size — note current peak_lr 3e-3 for dim 96), modern optimizers (Muon, AdamW-variants, schedule-free), data curriculum/quality selection beyond simple filtering, knowledge distillation from a larger teacher INTO a tiny student (we have GPU budget and could distill from a small open model — feasibility on one 32GB card alongside the 1M student), repeated-epoch vs fresh-data tradeoffs at 2B tokens for 1M params (this is massively over-trained — Chinchilla-optimal would be ~20M tokens; what do papers say about extreme overtraining and whether MORE tokens still help), and embedding/softmax tricks for byte-level models. Each finding must be implementable on one RTX 5090 in this codebase.`, { label: 'research-external', phase: 'Analyze', schema: FINDINGS }),
  () => agent(`${CONTEXT}\n\nRead /home/lane/MythosMini/src/mythosmini/training/stm.py and src/mythosmini/benchmarks/*.py. The STM phase runs at ~76 ktok/s while main training hits 1.19 Mtok/s — find out why (per-sample loss with reduction=none doubling memory? fixed loops=4? micro 128 after OOM shrink? flex recompiles from varying batch shapes — note dynamo recompile limit 8 with dynamic=False compile of flex_attention? the final partial batch shape?) and propose concrete speedups with exact code changes. Also check the benchmark phase for waste (it re-benchmarks every checkpoint each tournament generation?). Target: STM phase at >=500 ktok/s.`, { label: 'stm-speed', phase: 'Analyze', schema: FINDINGS }),
  () => agent(`${CONTEXT}\n\nRead /home/lane/MythosMini/train.py, src/mythosmini/hardware/autotune.py, src/mythosmini/training/loop.py, src/mythosmini/data/cache.py. Training currently 1.19 Mtok/s at micro 64 (autotuned; dense model used to autotune to 256 and hit 2.4 Mtok/s). Find remaining throughput: why does autotune now pick 64 (selection buffer memory? O(n^2) bool mask at batch 256 = 256*512*512 bools?), can selection construction be cheaper (uint8/bitpack, fused topk, computing selection at bf16, smaller LOCAL_WINDOW_BONUS dtype effects), can flex attention's backward be made cheaper, is grad_accum=1 with micro 64 leaving the GPU underutilized vs micro 128 + selection in chunks? Propose exact changes.`, { label: 'train-speed', phase: 'Analyze', schema: FINDINGS }),
])

phase('Verify')
const all = results.filter(Boolean).flatMap((r, i) => r.findings.map(f => ({ ...f, src: ['history', 'code', 'external', 'stm-speed', 'train-speed'][i] })))
log(`${all.length} raw findings collected`)
const verified = await parallel(all.map(f => () =>
  agent(`${CONTEXT}\n\nAdversarially review this proposal for the MythosMini codebase. Read the actual code it touches before judging. Refute it if: already tried and failed per journal.md, theoretically unsound at 1M params, won't fit one RTX 5090, conflicts with the leaderboard benchmark setup (byte-level, fixed eval), or the expected gain is wishful. PROPOSAL [from ${f.src}]: ${f.title} — ${f.detail} — expected: ${f.expected_gain} — risk: ${f.risk}`, { label: `verify:${f.title.slice(0, 30)}`, phase: 'Verify', schema: VERDICT })
    .then(v => ({ ...f, verdict: v }))
))
const sound = verified.filter(Boolean).filter(f => f.verdict?.is_sound)
log(`${sound.length}/${all.length} findings survived adversarial review`)

phase('Synthesize')
const plan = await agent(`${CONTEXT}\n\nYou are the lead architect. Here are adversarially-verified findings for maximizing the MythosMini leaderboard score (recover 59.47->60.4+, then exceed it) and throughput. Produce a final ordered implementation plan: max 8 changes, ordered by (expected gain / effort), each with exact files, exact change description, and how to verify. Mark which changes are QUALITY vs SPEED. Respect the repo rule: one training-behavior feature per 2B verification run — so group changes into at most 2 run-batches (batch 1 = quality recovery + best wins, batch 2 = optional second run). FINDINGS:\n${JSON.stringify(sound, null, 1)}`, { label: 'synthesizer', phase: 'Synthesize' })
return { plan, soundCount: sound.length, totalCount: all.length }
